module adder_32bit(
    input [32:1] A,
    input [32:1] B,
    output [32:1] S,
    output C32
);
    // TODO: Please add your logic design here
    wire [32:0] C;
    wire [32:0] P;
    wire [32:0] G;
    assign C[0] = 0;
    genvar i;
    generate
        for (i = 1; i <= 32; i = i + 1) begin
            assign P[i] = A[i] ^ B[i];
            assign G[i] = A[i] & B[i];
            assign C[i] = G[i] | (P[i] & C[i-1]);
            assign S[i] = P[i] ^ C[i-1];
        end
    endgenerate
    assign C32 = C[32];
endmodule
